import{_ as s,o,c as a,a0 as t}from"./chunks/framework.B27pdwYF.js";const u=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),n={name:"explanation/decisions.md"};function r(i,e,d,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite — the decisions that shape lasius, the alternatives rejected, and the consequence each carries.</p><h2 id="independent-clones-not-submodules" tabindex="-1">Independent clones, not submodules <a class="header-anchor" href="#independent-clones-not-submodules" aria-label="Permalink to &quot;Independent clones, not submodules&quot;">​</a></h2><p><strong>Decision:</strong> every org repo is a full git clone under <code>repos/</code> — no submodules, no monorepo merge.</p><p><strong>Alternatives:</strong> git submodules (each clone carries <code>.git</code> file pointer complexity, <code>git pull</code> doesn&#39;t recurse cleanly, editors see nested repos); a single merged repo (loses per-repo history, remotes, and CI boundaries).</p><p><strong>Consequence:</strong> each repo stays independent — its own branches, hooks, and workflows — while lasius provides the <em>management</em> layer on top. The cost: N clones of shared history and <code>repos/</code> must stay gitignored.</p><h2 id="local-clones-are-the-source-of-truth" tabindex="-1">Local clones are the source of truth <a class="header-anchor" href="#local-clones-are-the-source-of-truth" aria-label="Permalink to &quot;Local clones are the source of truth&quot;">​</a></h2><p><strong>Decision:</strong> <code>status</code>, <code>update</code>, and <code>code-workspace generate</code> iterate the clones on disk, not the provider&#39;s repo list.</p><p><strong>Alternatives:</strong> drive everything from <code>gh repo list</code> (a repo deleted upstream vanishes from status while its clone rots; manually added clones become invisible); a manifest file listing clones (drift between manifest and disk).</p><p><strong>Consequence:</strong> <code>lasius add &lt;name&gt;</code> and hand-cloned dirs are first-class; a repo deleted upstream keeps getting pulled until <code>lasius rm</code> removes it — visible, not silent.</p><h2 id="rm-is-paranoid-by-default" tabindex="-1"><code>rm</code> is paranoid by default <a class="header-anchor" href="#rm-is-paranoid-by-default" aria-label="Permalink to &quot;`rm` is paranoid by default&quot;">​</a></h2><p><strong>Decision:</strong> removal runs a checklist — clean tree, no unpushed commits, no stash, no linked worktrees, no nested <code>.git</code>, no extra remotes — and refuses unless <code>--force</code>.</p><p><strong>Alternatives:</strong> <code>rm -rf</code> semantics (one bad call loses uncommitted work across an org); confirm-prompt-only (a tired human still nukes a dirty tree).</p><p><strong>Consequence:</strong> the destructive verb is safe to expose to agents and scripts; <code>--force</code> exists for the cases the checklist can&#39;t see, and every refusal names what it found.</p><h2 id="vcs-and-forge-are-shared-ports-not-lasius-internals" tabindex="-1">VCS and forge are shared ports, not lasius internals <a class="header-anchor" href="#vcs-and-forge-are-shared-ports-not-lasius-internals" aria-label="Permalink to &quot;VCS and forge are shared ports, not lasius internals&quot;">​</a></h2><p><strong>Decision:</strong> <code>lasius-vcs</code> and <code>lasius-forge</code> are trait crates consumed by other repos (tarsi, mimus, bupha, kuda, sturn) for their agentic-CI surfaces (P-019); lasius-cli just happens to be the first consumer.</p><p><strong>Alternatives:</strong> per-repo git/gh wrappers (N implementations of <code>worktree_add</code>/<code>create_status</code> drifting apart); a lasius-specific API other repos can&#39;t use.</p><p><strong>Consequence:</strong> workspace expertise is reusable — any engine can shell out to git/gh through the same tested port. The crates are dependency-light and sync on purpose.</p><h2 id="the-command-ships-as-a-tamias-pack" tabindex="-1">The command ships as a tamias pack <a class="header-anchor" href="#the-command-ships-as-a-tamias-pack" aria-label="Permalink to &quot;The command ships as a tamias pack&quot;">​</a></h2><p><strong>Decision:</strong> there is no cargo-installed <code>lasius</code> binary — the command is a generated <code>bins[]</code> shim over <code>tamias-driver-lasius</code> via <code>libraries/lasius</code>.</p><p><strong>Alternatives:</strong> a <code>[[bin]]</code> in lasius-cli (a second distribution path to keep in sync with the driver); per-repo install scripts (drift).</p><p><strong>Consequence:</strong> one artifact serves both humans (<code>lasius</code> shim) and agents (<code>cli.&lt;verb&gt;</code> wire queries, <code>run</code>/<code>cli</code> passthroughs) — install, upgrade, and rollback are tamias&#39;s problem.</p>',22)])])}const m=s(n,[["render",r]]);export{u as __pageData,m as default};
